/**
 * buzz-map 集客ゲート: 人が選定した企画 SSOT (curated ideas)
 *
 * 正典: このファイル（企画）/ .claude/rules/buzz-map-standards.md §4-5（運用・landing gate）
 * 規約: .claude/rules/buzz-map-standards.md / .claude/rules/sns-content-standards.md
 *
 * このファイルは企画の唯一の authored source。build-buzz-map-catalog.ts が machine lane と
 * このファイルを統合し、重複を解消して state JSON (.claude/state/sns/buzz-map-catalog.json) を生成する。
 * state JSON を直接編集しない。ここだけを編集する。
 *
 * 各エントリの metricKeys は「実在確認済みの key のみ」を持つ (packages/data-configs/src/metrics/<key>.ts
 * または machine catalog の metricKey で照合)。実在確認できない場合は [] + feasibility:"needs-data"。
 * ダミーデータ・存在しない metricKey の捏造はしない。
 */

// ---------------------------------------------------------------------------
// 型 (仕様 §4.2)
// ---------------------------------------------------------------------------

export type LandingStrategy =
  | "existing-ranking"
  | "existing-blog"
  | "existing-theme"
  | "extend-theme"
  | "create-blog"
  | "create-theme"
  | "blocked";

export type LandingReadiness =
  | "ready"
  | "needs-content"
  | "draft"
  | "review-passed"
  | "publish-pending"
  | "live"
  | "blocked";

export interface BuzzMapLandingPlan {
  strategy: LandingStrategy;
  readiness: LandingReadiness;
  primaryUrl: string | null;
  primaryKey: string | null;
  secondaryUrls: string[];
  articleSlug: string | null;
  themeSlug: string | null;
  landingPromise: string;
  ctaLabel: string;
  searchIntent: string | null;
  monetizationVertical: "none" | "housing" | "mobility" | "labor" | "education";
  attributionByChannel: Partial<
    Record<"x" | "instagram", "direct" | "profile" | "unattributed">
  >;
  blockers: string[];
}

export interface CuratedBuzzMapIdea {
  ideaId: string;
  title: string;
  subtitle: string;
  hook: string;
  question: string;
  level: "pref" | "muni" | "mesh";
  recommendedType: "A" | "B" | "C" | "D" | "E" | "F" | "flow";
  category: string;
  sourceKind: "estat" | "ksj" | "mlit-dpf" | "gsi" | "derived" | "external";
  metricKeys: string[];
  /** 同義候補を1件へ統合した際の別名・別候補 */
  aliases?: string[];
  dataRefs: Array<{
    id: string;
    version?: string;
    year?: string;
    license: string;
    sourceUrl?: string;
  }>;
  viralPatterns: string[];
  externalEvidence: Array<{ url: string; note: string; surveyedAt: string }>;
  gscEvidence: Array<{
    query: string;
    impressions?: number;
    clicks?: number;
    week?: string;
  }>;
  competitorOverlap: "none" | "partial" | "exact";
  feasibility: "now" | "needs-pipeline" | "needs-renderer" | "needs-data";
  capability: string;
  commercialUse: "allowed" | "review-required" | "blocked";
  sensitivity: "low" | "medium" | "high";
  priority: "P0" | "P1" | "P2" | "P3";
  score: number;
  scoreBreakdown: Record<string, number>;
  blockers: string[];
  channels: Array<"x" | "instagram">;
  renderPlan: string;
  landingPlan: BuzzMapLandingPlan;
}

// ---------------------------------------------------------------------------
// 共通ヘルパー: license / dataRef の定型化 (二重管理を避ける)
// ---------------------------------------------------------------------------

const ESTAT_LICENSE = "estat-terms (commercial-ok)";
const GSI_LICENSE = "出典明示で商用可 (測量法・国土地理院コンテンツ利用規約)";

/** e-Stat 由来の観測値 metricKey を dataRef へ */
const estatRefs = (
  keys: string[],
  year?: string,
): CuratedBuzzMapIdea["dataRefs"] =>
  keys.map((id) => ({ id, license: ESTAT_LICENSE, ...(year ? { year } : {}) }));

/** 型A/E で今すぐレンダ可能な pref/muni 観測値塗り分けの capability 定型 */
const CAP_AE = "型A 二値マップ + 型E 合成の塗りベース (実装済)";
const CAP_A = "型A 二値マップ (実装済)";
const CAP_B = "型B 四象限 scatter (2 指標の関係、実装済)";
const CAP_C = "型C 点プロット (実装済)";
const CAP_D_LINE = "型D 線ネットワーク・時系列リール (実装済)";
const CAP_D_ISO = "型D 到達圏 isochrone (道路 network 到達時間 renderer 未整備)";
const CAP_F_MESH = "型F メッシュ塗り (未実装)";
const CAP_FLOW = "型flow 移動フロー矢印 (OD flow renderer 未整備)";

